#include <gpiod.h>   // Provides the libgpiod GPIO functions.
#include <cstdio>    // Provides perror() for printing system errors.
#include <unistd.h>  // Provides sleep().

int main()
{
    // Open the GPIO chip; gpiochip0 is an example and may differ on your board.
    gpiod_chip* chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == nullptr) { perror("gpiod_chip_open"); return 1; }

    // Get GPIO line offsets; these are examples, not universal GPIO numbers.
    gpiod_line* m1a = gpiod_chip_get_line(chip, 17);
    gpiod_line* m1b = gpiod_chip_get_line(chip, 18);
    gpiod_line* m2a = gpiod_chip_get_line(chip, 22);
    gpiod_line* m2b = gpiod_chip_get_line(chip, 23);

    // Stop with an error if any requested line could not be found.
    if (!m1a || !m1b || !m2a || !m2b) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request each line as an output, initially LOW.
    if (gpiod_line_request_output(m1a, "l298n-m1a", 0) < 0 ||
        gpiod_line_request_output(m1b, "l298n-m1b", 0) < 0 ||
        gpiod_line_request_output(m2a, "l298n-m2a", 0) < 0 ||
        gpiod_line_request_output(m2b, "l298n-m2b", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set one input HIGH and the other LOW for each motor; this selects a direction.
    if (gpiod_line_set_value(m1a, 1) < 0 || gpiod_line_set_value(m1b, 0) < 0 ||
        gpiod_line_set_value(m2a, 1) < 0 || gpiod_line_set_value(m2b, 0) < 0) {
        perror("gpiod_line_set_value");
        gpiod_chip_close(chip);
        return 1;
    }

    // Keep both motors running in that direction for two seconds.
    sleep(2);

    // Swap each motor's input values to reverse its direction.
    if (gpiod_line_set_value(m1a, 0) < 0 || gpiod_line_set_value(m1b, 1) < 0 ||
        gpiod_line_set_value(m2a, 0) < 0 || gpiod_line_set_value(m2b, 1) < 0) {
        perror("gpiod_line_set_value");
        gpiod_chip_close(chip);
        return 1;
    }

    // Keep both motors running in reverse for two seconds.
    sleep(2);

    // Set both inputs LOW for each motor; this stops the motors (coasting on typical boards).
    if (gpiod_line_set_value(m1a, 0) < 0 || gpiod_line_set_value(m1b, 0) < 0 ||
        gpiod_line_set_value(m2a, 0) < 0 || gpiod_line_set_value(m2b, 0) < 0) {
        perror("gpiod_line_set_value");
        gpiod_chip_close(chip);
        return 1;
    }

    // Release the GPIO lines and close the chip before exiting.
    gpiod_line_release(m1a);
    gpiod_line_release(m1b);
    gpiod_line_release(m2a);
    gpiod_line_release(m2b);
    gpiod_chip_close(chip);
    return 0;
}
